// R4f-error E5 (transcript-09, WI-5): the host's input to the 2.42304.0 error-card retry decision.
//
// The original decides what the error card's Try again does with cee72b629 d (exported t; `lz` in cc43287c9, generated by
// scripts/extract-retry-decision.mjs as generated/retry-decision/retry-decision.mjs decideErrorRetry). Its two arguments come
// from the session bucket and the composer:
//   - e: cee72b629 f (`sz`): {error, errorKilledTurn, errorRejectedPrompt, heldInput, messages: the bucket's message snapshot,
//     desktopSession, conversationLost: shownCategory === "cli_resume_not_found", lastPrompt: desktopSession &&
//     cc8941b7b qt(messages, canned) || undefined}, with canned = c73f45bc3 yh (`MN`, generated cannedNudges).
//   - t: cc43287c9 b_ `lz(n, {text: r.getText(), isEmpty: !r.hasDraft()})`, where the composer's c227f4d5e hasDraft is
//     `!(e()?.isEmpty ?? !0) || _t.current` (editor not empty, or staged attachments).
// This host keeps no bucket: a Codex thread is `items` (ThreadItem rows tagged with turnId) plus `turnErrors` (a failed turn's
// TurnError), the thread-wide `errors[id]` with `errorKilledTurn[id]` (state.js) and `active[id]`. The functions below
// project those onto the fields and row shapes the original reads, so the decision itself stays the original's.
//
// Host answers (each is a structural difference, not a fallback):
//   - errorRejectedPrompt is null: a refused turn/start keeps its prompt in the 'Not delivered' bubble (pendingSends) with
//     its own Retry / Discard; it never reaches the error card, so "resend" is unreachable from the card.
//   - heldInput is []: the host has no parked / held session, so "deliver" is unreachable.
//   - desktopSession is true (every session runs on this machine's core) and conversationLost is false: the CLI's
//     cli_resume_not_found / "no conversation found with session id" only come from a Claude Code CLI core; a Codex resume
//     failure is an ensureResumed RPC error, never a card. Terminal rows carry no result / errors text either, so l() is
//     false too and "repeatPrompt" / "refillPrompt" are unreachable.
//   - lastPrompt.sentAt is undefined: a Codex userMessage has no timestamp (only the unreachable repeatPrompt reads it).
import { decideErrorRetry } from "./generated/retry-decision/retry-decision.mjs";
import { retryNudgeMessages, cannedNudges } from "./generated/retry-decision/retry-nudge-messages.mjs";
import { isEmptyComposerText } from "./prompt-history-model.mjs";
import { t } from "../electron/i18n/index.mjs";

// ThreadItem types (codex v2 ThreadItem) the agent produced within a turn: what the original's assistant rows carry (text,
// thinking and tool_use blocks). userMessage is the human prompt row; hookPrompt (isMeta), functionCallOutput (a tool_result
// user row), contextCompaction, enteredReviewMode / exitedReviewMode and subAgentActivity (parent_tool_use_id rows) are none
// of the rows d / s / c read, so they are left out.
export const RETRY_ASSISTANT_ITEM_TYPES = Object.freeze(["agentMessage", "reasoning", "plan", "commandExecution", "fileChange",
  "mcpToolCall", "dynamicToolCall", "collabAgentToolCall", "webSearch", "imageView", "imageGeneration", "sleep"]);
const ASSISTANT = new Set(RETRY_ASSISTANT_ITEM_TYPES);

const own = (object, key) => !!object && Object.prototype.hasOwnProperty.call(object, key);
const textOf = (item) => (Array.isArray(item?.content) ? item.content : [])
  .filter((part) => part?.type === "text" && typeof part.text === "string").map((part) => part.text).join("\n");

// A userMessage's UserInput parts as the original's user content blocks: text stays text (so shared-104 XC / rw read the
// same prompt text the original would), image / localImage are image blocks; skill / mention are composer-only inputs with
// no content block. None of these is a tool_result block (shared-52 WR), so a userMessage is never a tool_result row.
function userContent(item) {
  return (Array.isArray(item?.content) ? item.content : []).flatMap((part) =>
    part?.type === "text" && typeof part.text === "string" ? [{ type: "text", text: part.text }]
      : part?.type === "image" || part?.type === "localImage" ? [{ type: "image" }] : []);
}

// The thread's latest turn: the last item's turnId (turn-error-model turnErrorPlacements' `latest` without an active turn).
function latestTurnId(items) {
  for (let index = (items || []).length - 1; index >= 0; index--) if (items[index]?.turnId) return items[index].turnId;
  return null;
}

// The original's message rows in their smallest form, in item order:
//   userMessage                     -> {type: "user", uuid, message: {content}}   a human prompt (shared-104 eC: a user row,
//                                      not isSynthetic / isMeta, uuid not "client-", no tool_result block, not a /model
//                                      local command)
//   an item the agent produced      -> {type: "assistant"}
//   after the last item of a turn   -> {type: "result", is_error} the terminal row (shared-104 QS), unless the turn is the
//                                      active one: a running turn has no terminal row yet, so sC meets its prompt first and
//                                      s() asks oC, which finds that prompt still waiting for its result.
// is_error is true for a turn with a TurnError (turnErrors[turnId]) and for `killedTurnId`, the turn a thread-wide error
// cut short (the original's killed turn has no successful result row: shared-104 lC reads only a success as finished).
// Items without a turnId (none in a Codex thread) are not part of any turn and are skipped.
export function projectRetryMessages(items, turnErrors, { active = null, killedTurnId = null } = {}) {
  const list = Array.isArray(items) ? items : [];
  const lastIndex = new Map();
  list.forEach((item, index) => { if (item?.turnId) lastIndex.set(item.turnId, index); });
  const rows = [];
  list.forEach((item, index) => {
    const turnId = item?.turnId;
    if (!turnId) return;
    if (item.type === "userMessage") rows.push({ type: "user",
      uuid: typeof item.id === "string" && item.id ? item.id : `${turnId}:user:${index}`, message: { content: userContent(item) } });
    else if (ASSISTANT.has(item.type)) rows.push({ type: "assistant" });
    if (lastIndex.get(turnId) === index && turnId !== active)
      rows.push({ type: "result", is_error: (own(turnErrors, turnId) && !!turnErrors[turnId]) || turnId === killedTurnId });
  });
  return rows;
}

// cc8941b7b qt (`lastPromptToSendAgain`): the thread's last human prompt, or undefined. Its text joins the text parts with
// "\n" (the user row's text, prompt-history-model humanPrompts); an empty text or one of the canned nudges (c73f45bc3 yh,
// generated cannedNudges: the localized and English "Try again" / after-usage-limit / after-sleep copy) is none.
// whole: every part is text (no image / localImage / skill / mention input). sentAt: none, see the header.
export function lastRetryPrompt(items, canned = []) {
  const item = (Array.isArray(items) ? items : []).findLast((entry) => entry?.type === "userMessage" && entry.turnId);
  if (!item || typeof item.id !== "string" || !item.id) return undefined;
  const text = textOf(item);
  if (!text.trim() || (Array.isArray(canned) && canned.includes(text.trim()))) return undefined;
  const content = Array.isArray(item.content) ? item.content : [];
  return { uuid: item.id, text, sentAt: undefined, whole: content.length > 0 && content.every((part) => part?.type === "text" && typeof part.text === "string") };
}

// The decision's first argument (cee72b629 f's shape) for one error card:
//   - a turn card (no threadError): the failed turn's TurnError, turnErrors[turnId]. It is always on a turn that started, so
//     errorKilledTurn is true (the original's "error" event sets it when a turn was pending).
//   - the thread card (threadError = state.errors[id]): errorKilledTurn is `killedTurn` (state.errorKilledTurn[id]: a turn
//     was running when it arrived, c06cf64bb `t.pendingTurn!==null||t.errorKilledTurn`); a killed turn that is no longer
//     active ends in a failed terminal row.
// error is the message text (the bucket's error is a string; d only asks whether it is null).
export function retryTurnState(items, turnErrors, { turnId = null, threadError = null, killedTurn = false, active = null, canned = [] } = {}) {
  const thread = !!threadError;
  const failure = thread ? threadError : turnId && own(turnErrors, turnId) && turnErrors[turnId] ? turnErrors[turnId] : null;
  const errorKilledTurn = failure !== null && (thread ? killedTurn === true : true);
  // A still-running killed turn has no terminal row at all; one that stopped running is the thread's latest turn.
  const killedTurnId = thread && errorKilledTurn && !active ? latestTurnId(items) : null;
  return {
    error: failure === null ? null : typeof failure.message === "string" ? failure.message : "",
    errorKilledTurn,
    errorRejectedPrompt: null,
    heldInput: [],
    messages: projectRetryMessages(items, turnErrors, { active, killedTurnId }),
    desktopSession: true,
    conversationLost: false,
    lastPrompt: lastRetryPrompt(items, canned),
  };
}

// The decision's second argument: {text: getText(), isEmpty: !hasDraft()} with hasDraft = editor not empty (tiptap isEmpty:
// only empty paragraphs, prompt-history-model isEmptyComposerText) or staged attachments.
export function composerRetryInput(draft, attachments) {
  const text = typeof draft === "string" ? draft : "";
  return { text, isEmpty: isEmptyComposerText(text) && !(Array.isArray(attachments) && attachments.length > 0) };
}

// The host intl for the generated copy: messages format through the host dictionary by their defaultMessage (as the other
// source adapters do). cc43287c9 formats the nudge before sending (V.formatMessage(xN.retryNudge)), so the model receives
// the localized text, as in the original.
const hostIntl = (translate) => ({ formatMessage: ({ defaultMessage }, values) => translate(defaultMessage, values) });

// c73f45bc3 vh.retryNudge ("Try again", FazwRldA7z), localized.
export function retryNudgeText(translate = t) {
  return hostIntl(translate).formatMessage(retryNudgeMessages.retryNudge);
}

// c73f45bc3 yh (`MN(V)`): the canned copy lastPrompt skips (localized first, then the English originals).
export function retryCannedNudges(translate = t) {
  return cannedNudges(hostIntl(translate));
}

// The nudge as a turn/start input: the localized retryNudge text as one text part.
export function retryNudgeInput(text) {
  return [{ type: "text", text: String(text ?? ""), text_elements: [] }];
}

// cc43287c9 b_'s `a = lz(n, {text: r.getText(), isEmpty: !r.hasDraft()})` for one host error card. Returns the original's
// result: "nudge" | "nudgeBesideDraft" | "focus" (reachable on this host), or "resend" | "repeatPrompt" | "refillPrompt" |
// "deliver" (unreachable, see the header). `now` is d's third argument (Date.now() by default).
export function errorCardRetryDecision({ items, turnErrors, turnId = null, threadError = null, killedTurn = false, active = null,
  draft = "", attachments = [], translate = t, now } = {}) {
  const state = retryTurnState(items, turnErrors, { turnId, threadError, killedTurn, active, canned: retryCannedNudges(translate) });
  const input = composerRetryInput(draft, attachments);
  return now === undefined ? decideErrorRetry(state, input) : decideErrorRetry(state, input, now);
}
